        refreshTaxRankReportIfVisible();
        downloadReportImage(e);
    }, true);
    document.getElementById('downloadPdfBtn').addEventListener('click', function(e) {
        refreshTaxRankReportIfVisible();
        downloadReportPdf(e);
    }, true);
    document.getElementById('sharePngBtn').addEventListener('click', function(e) {
        shareTaxRankPng(e);
    }, true);
    renderIcons();
});
